"""Two synthetic sessions: stale edits, validation/reclassification, notice, cancellation and remembered Personal unit."""
import asyncio
from playwright.async_api import async_playwright
HOST='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ca=await b.new_context(viewport={'width':1440,'height':1000});cw=await b.new_context(viewport={'width':1300,'height':900})
  for c in [ca,cw]:await c.route('https://**/*',lambda r:r.abort());await c.add_init_script('window.print=()=>{}')
  admin=await ca.new_page();worker=await cw.new_page();errors=[]
  for p in[admin,worker]:p.on('pageerror',lambda e:errors.append(str(e)));p.on('dialog',lambda d:d.accept())
  async def login(p,m):
   await p.goto(HOST+'/login');await p.locator('input[type=text]').first.fill(m);await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('nav.sidebar').wait_for()
  async def api(p,path,method='GET',d=None):return await p.evaluate('(v)=>window.SICIPCentral.api(v.path,{method:v.method,...(v.d?{body:JSON.stringify(v.d)}:{})})',{'path':path,'method':method,'d':d})
  await login(admin,'TESTADMIN');await login(worker,'TESTUSER')
  for clave in['A','B']:await api(admin,'/api/admin/unidades','POST',{'clave':clave,'nombre':'Unidad '+clave,'activo':True,'version':0})
  await api(admin,'/api/admin/unidades/asignar','POST',{'unidad':'A','matriculas':['TESTUSER']});day=(await api(worker,'/api/inicio'))['fecha'];folio=(await api(worker,'/api/pases/folio','POST',{'request_id':'aaaaaaaa-1111-4111-8111-222222222222'}))['folio'];await api(worker,'/api/pases/registros','POST',{'folio':folio,'matricula':'TESTUSER','nombre':'Trabajador de prueba','categoria':'Categoría','servicio':'Servicio','fecha':day,'hora':'12:00','tipoAsunto':'OFICIAL','tipoHorario':'SALIDA','destino':'Oficina','motivo':'Comisión oficial inicial','objeto':'Sin regreso','estado':'PENDIENTE_ENTREGA'})
  await worker.goto(HOST+'/pases/index.html?scope=trabajador');await worker.locator('[data-pass-edit="'+folio+'"]').wait_for();await worker.locator('[data-pass-edit="'+folio+'"]').click();d=worker.locator('.pase-edit-dialog');await d.locator('[name=motivo]').fill('Comisión con información corregida');await d.locator('[name=hora]').fill('13:00');assert await d.locator('[name=unidad_clave]').count()==0;await d.get_by_role('button',name='Guardar cambios').click();await d.wait_for(state='detached');assert (await api(worker,'/api/pases/registros?folio='+folio))['hora']=='13:00';print('Trabajador edita pendiente, conserva folio y unidad asignada.',flush=True)
  await admin.goto(HOST+'/recepciones');await admin.locator('[data-sicip-recepciones-panel]').wait_for();await admin.wait_for_function('window.SICIPRecepcion');await admin.evaluate('(f)=>{window.__SICIP_RECEP_SHOW_FOLIO__();return window.SICIPRecepcion.buscar(f,document.getElementById("sicip-recep-folio-result"))}',folio);await admin.evaluate('document.getElementById("sicip-recep-folio-result").style.display="block"');assert 'OFICIAL' in await admin.locator('#sicip-recep-folio-result').inner_text();await admin.locator('#sicip-recep-folio-result [data-receive]').click();assert 'Valida los datos' in await admin.locator('#sicip-recep-folio-result').inner_text();assert (await api(worker,'/api/pases/registros?folio='+folio))['estado']=='PENDIENTE_ENTREGA'
  await admin.goto(HOST+'/pases/index.html?scope=personal');await admin.locator('[data-pass-unit]').select_option('B');await admin.get_by_text('Unidad guardada para tus próximos pases:',exact=False).wait_for();await admin.reload();await admin.wait_for_function("document.querySelector('[data-pass-unit]')?.value==='B'")
  # Leave worker's edit open; Personal receives simultaneously.
  await worker.locator('[data-pass-edit="'+folio+'"]').click();await worker.locator('.pase-edit-dialog [name=motivo]').fill('Este cambio ya no debe guardarse');row=admin.locator('#passesTbody tr').filter(has_text=folio);await row.get_by_role('button',name='Validar y recibir',exact=True).click();d=admin.locator('.pase-edit-dialog');await d.locator('[name=validado]').check();await d.get_by_role('button',name='Confirmar recepción',exact=True).click();await d.wait_for(state='detached');await worker.locator('.pase-edit-dialog [data-save]').click();await worker.locator('.pase-edit-dialog [data-status]').get_by_text('El pase ya fue entregado.',exact=False).wait_for();await worker.locator('.pase-edit-dialog [data-close]').click();await worker.evaluate('window.SICIPPasesSync.refresh()');assert await worker.locator('[data-pass-edit="'+folio+'"],[data-pass-cancel="'+folio+'"]').count()==0;assert (await api(worker,'/api/pases/registros?folio='+folio))['motivo']=='Comisión con información corregida';print('Recepción bloquea una edición ya abierta y retira Editar/Cancelar del trabajador.',flush=True)
  await row.get_by_role('button',name='Reclasificar',exact=True).click();d=admin.locator('.pase-edit-dialog');assert await d.locator('[name=hora]').count()==0;await d.locator('[name=justificacion]').fill('No presenta la comisión oficial autorizada que justifique el pase.');await d.get_by_role('button',name='Guardar cambios').click();await d.wait_for(state='detached');r=await api(worker,'/api/pases/registros?folio='+folio);assert r['estado']=='RECIBIDO_PERSONAL' and r['tipoAsunto']=='PARTICULAR';notices=await api(worker,'/api/notificaciones');assert any('no cumple los requisitos de pase oficial' in n['mensaje'] for n in notices['notificaciones']);await row.get_by_role('button',name='Cancelar',exact=True).click();await admin.locator('.pase-edit-dialog [name=justificacion]').fill('Cancelación por duplicidad confirmada en el Departamento de Personal.');await admin.locator('.pase-edit-dialog [data-save]').click();await admin.locator('.pase-edit-dialog').wait_for(state='detached');assert (await api(worker,'/api/pases/registros?folio='+folio))['estado']=='CANCELADO';print('Personal reclasifica con motivo, notifica y cancela recibido conservando historial.',flush=True)
  await admin.locator('[data-pass-path=manual]').click();await admin.locator('#manualMatricula').fill('TESTUSER');await admin.locator('#manualTipoAsunto').select_option('PARTICULAR');await admin.locator('#manualTipoHorario').select_option('SALIDA');await admin.locator('#manualFecha').fill(day);await admin.locator('#manualHora').fill('14:00');await admin.locator('#manualForm').get_by_role('button',name='Relacionar pase manual',exact=True).click();await admin.wait_for_function("window.SICIPPasesStorage.read().some(p=>p.origen==='MANUAL')");rows=(await api(admin,'/api/pases/registros'))['pases'];manual=next(x for x in rows if x.get('origen')=='MANUAL');assert manual['unidad_clave']=='B';assert (await api(worker,'/api/unidades/contexto'))['unidad']['clave']=='A';await admin.set_viewport_size({'width':390,'height':844});await admin.locator('[data-pass-edit="'+manual['folio']+'"]').click();assert await admin.evaluate('document.documentElement.scrollWidth<=innerWidth+1');assert not errors,errors;await b.close();print('Unidad de Personal persistida, aplicada al pase sin cambiar adscripción; vista móvil comprobada.',flush=True)
asyncio.run(main())
